-- Gestionnaire : les troupes ne prennent sur la réserve du prochain bâtiment que leur part de la production.
-- Jusqu'à cette date, elles n'utilisent plus que l'excédent.
ALTER TABLE manager_villages ADD COLUMN troops_until TIMESTAMPTZ;

-- Les modèles de départ jamais modifiés par leur joueur passent aux nouveaux réglages optimisés.
UPDATE manager_templates SET buildings = '[{"building":"woodcutter","level":3},{"building":"claypit","level":3},{"building":"ironmine","level":3},{"building":"farm","level":3},{"building":"warehouse","level":3},{"building":"townhall","level":3},{"building":"barracks","level":3},{"building":"woodcutter","level":7},{"building":"claypit","level":7},{"building":"ironmine","level":7},{"building":"farm","level":6},{"building":"warehouse","level":7},{"building":"townhall","level":5},{"building":"barracks","level":5},{"building":"woodcutter","level":10},{"building":"claypit","level":10},{"building":"ironmine","level":10},{"building":"farm","level":10},{"building":"warehouse","level":11},{"building":"townhall","level":10},{"building":"woodcutter","level":15},{"building":"claypit","level":15},{"building":"ironmine","level":15},{"building":"farm","level":14},{"building":"warehouse","level":15},{"building":"barracks","level":15},{"building":"woodcutter","level":20},{"building":"claypit","level":20},{"building":"ironmine","level":20},{"building":"farm","level":20},{"building":"townhall","level":20},{"building":"barracks","level":25},{"building":"warehouse","level":22},{"building":"wall","level":10},{"building":"woodcutter","level":25},{"building":"claypit","level":25},{"building":"ironmine","level":25},{"building":"warehouse","level":26},{"building":"woodcutter","level":30},{"building":"claypit","level":30},{"building":"ironmine","level":30},{"building":"warehouse","level":30}]'::jsonb,
  troops = '{"swordsman":11500,"cavalry":1800,"ram":150,"scout":50}'::jsonb, troops_share = 15
WHERE name = 'Offensif' AND buildings = '[{"building":"farm","level":8},{"building":"warehouse","level":8},{"building":"barracks","level":10},{"building":"woodcutter","level":10},{"building":"claypit","level":10},{"building":"ironmine","level":10},{"building":"farm","level":15},{"building":"barracks","level":15},{"building":"warehouse","level":14},{"building":"farm","level":20},{"building":"barracks","level":20}]'::jsonb
  AND troops = '{"swordsman":2000,"cavalry":800,"ram":100,"scout":40}'::jsonb AND troops_share = 30;

UPDATE manager_templates SET buildings = '[{"building":"woodcutter","level":3},{"building":"claypit","level":3},{"building":"ironmine","level":3},{"building":"farm","level":3},{"building":"warehouse","level":3},{"building":"townhall","level":3},{"building":"barracks","level":4},{"building":"woodcutter","level":7},{"building":"claypit","level":7},{"building":"ironmine","level":7},{"building":"farm","level":6},{"building":"warehouse","level":7},{"building":"wall","level":5},{"building":"townhall","level":5},{"building":"woodcutter","level":10},{"building":"claypit","level":10},{"building":"ironmine","level":10},{"building":"farm","level":10},{"building":"warehouse","level":11},{"building":"wall","level":10},{"building":"townhall","level":10},{"building":"woodcutter","level":15},{"building":"claypit","level":15},{"building":"ironmine","level":15},{"building":"farm","level":14},{"building":"warehouse","level":15},{"building":"barracks","level":12},{"building":"wall","level":15},{"building":"woodcutter","level":20},{"building":"claypit","level":20},{"building":"ironmine","level":20},{"building":"farm","level":20},{"building":"wall","level":20},{"building":"townhall","level":20},{"building":"barracks","level":20},{"building":"warehouse","level":22},{"building":"barracks","level":25},{"building":"woodcutter","level":25},{"building":"claypit","level":25},{"building":"ironmine","level":25},{"building":"warehouse","level":26},{"building":"woodcutter","level":30},{"building":"claypit","level":30},{"building":"ironmine","level":30},{"building":"warehouse","level":30}]'::jsonb,
  troops = '{"spearman":9500,"halberdier":9900,"scout":250}'::jsonb, troops_share = 25
WHERE name = 'Défensif' AND buildings = '[{"building":"farm","level":10},{"building":"warehouse","level":10},{"building":"barracks","level":8},{"building":"wall","level":10},{"building":"woodcutter","level":10},{"building":"claypit","level":10},{"building":"ironmine","level":10},{"building":"farm","level":20},{"building":"wall","level":20},{"building":"warehouse","level":16}]'::jsonb
